// Source files bundled as plain text by esbuild (loader "text") for the examples menu.
declare module "*.txt" {
  const text: string;
  export default text;
}
declare module "*.mmd" {
  const text: string;
  export default text;
}
declare module "*.puml" {
  const text: string;
  export default text;
}
declare module "*.drawio" {
  const text: string;
  export default text;
}
